           cyanTarget = isDark ? "#38bdf8" : "#0284c7",
           magentaPlasma = isDark ? "#e879f9" : "#c026d3",
           leftX = startX;
          ctx.fillStyle = isDark ? "#e6edf3" : "#111111";
          ctx.font = titleFont;
