              ctx.createRadialGradient
               (pStrike[0], pStrike[1], 1.5, pStrike[0], pStrike[1], glowR),
            gAlpha = Math.max(0.28, 0.72 - 0.35 * (st.quench || 0.0));
           grad.addColorStop
            (0.0, "rgba(251,146,60," + gAlpha.toFixed(2) + ")");
           grad.addColorStop
            (0.45, "rgba(239,68,68," + (gAlpha * 0.65).toFixed(2) + ")");
           grad.addColorStop(1.0, "rgba(239,68,68,0)");
           ctx.fillStyle = grad;
